// Command gen generates messages_generated.go from the Firebird message
// definition headers (src/include/firebird/impl/msg/*.h).
//
// Usage:
//
//	go run ./gen                  # downloads the headers from GitHub (master)
//	go run ./gen -ref v5.0.3      # downloads from a specific tag/branch
//	go run ./gen -dir path/to/msg # uses local header files
//
// The message texts are © Firebird project contributors, distributed under
// the Initial Developer's Public License (IDPL); see the generated file.
package main

import (
	"flag"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

// facilities maps header basename → FB_IMPL_MSG_FACILITY_* code
// (src/include/firebird/impl/msg_helper.h). Only facilities whose codes can
// reach a client status vector are included.
var facilities = []struct {
	file string
	code int
}{
	{"jrd", 0},
	{"gfix", 3},
	{"dsql", 7},
	{"dyn", 8},
	{"gbak", 12},
	{"sqlerr", 13},
	{"sqlwarn", 14},
	{"jrd_bugchk", 15},
	{"isql", 17},
	{"gsec", 18},
	{"gstat", 21},
	{"fbsvcmgr", 22},
	{"utl", 23},
	{"nbackup", 24},
	{"fbtracemgr", 25},
}

const gdsMask = 0x14000000

// FB_IMPL_MSG(FACILITY, num, symbol, sqlcode, "cl", "sub", "text")
// FB_IMPL_MSG_SYMBOL(FACILITY, num, symbol, "text")
// FB_IMPL_MSG_NO_SYMBOL(FACILITY, num, "text")
// El `.*` codicioso del medio salta los argumentos intermedios (incluidos los
// strings de sqlclass/subclass) dejando el ÚLTIMO string como texto del mensaje.
var entryRe = regexp.MustCompile(`^FB_IMPL_MSG(?:_NO_SYMBOL|_SYMBOL)?\(\s*(\w+),\s*(\d+)\s*,(?:.*,)?\s*"((?:[^"\\]|\\.)*)"\s*\)\s*$`)

func main() {
	ref := flag.String("ref", "master", "Firebird git ref to download headers from")
	dir := flag.String("dir", "", "local directory with the .h files (skips download)")
	out := flag.String("out", "messages_generated.go", "output file")
	flag.Parse()

	type msg struct {
		code int32
		text string
	}
	var msgs []msg

	for _, fac := range facilities {
		var content []byte
		var err error
		if *dir != "" {
			content, err = os.ReadFile(filepath.Join(*dir, fac.file+".h"))
		} else {
			content, err = download(*ref, fac.file)
		}
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s: %v\n", fac.file, err)
			os.Exit(1)
		}
		for _, line := range strings.Split(string(content), "\n") {
			line = strings.TrimSpace(line)
			m := entryRe.FindStringSubmatch(line)
			if m == nil {
				continue
			}
			num, err := strconv.Atoi(m[2])
			if err != nil || num < 0 || num > 0x3FFF {
				continue
			}
			text := unescapeC(m[3])
			if text == "" {
				continue
			}
			code := int32(gdsMask | fac.code<<16 | num)
			msgs = append(msgs, msg{code, text})
		}
	}

	sort.Slice(msgs, func(i, j int) bool { return msgs[i].code < msgs[j].code })

	var b strings.Builder
	b.WriteString(`// Code generated by internal/errmsg/gen; DO NOT EDIT.
//
// Firebird error message templates, extracted from
// https://github.com/FirebirdSQL/firebird/tree/master/src/include/firebird/impl/msg
//
// The message texts are copyright of the Firebird project contributors and
// are distributed under the Initial Developer's Public License Version 1.0
// (IDPL, https://www.firebirdsql.org/en/initial-developer-s-public-license-version-1-0/).
// The rest of this module remains under its own license.

package errmsg

// Template returns the Firebird message template for a GDS error code, or
// the empty string when the code is unknown. Placeholders @1..@n are
// substituted with the status-vector arguments by Render.
func Template(code int32) string {
	switch code {
`)
	for _, m := range msgs {
		fmt.Fprintf(&b, "\tcase %d:\n\t\treturn %s\n", m.code, strconv.Quote(m.text))
	}
	b.WriteString(`	}
	return ""
}
`)
	if err := os.WriteFile(*out, []byte(b.String()), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	fmt.Printf("%d mensajes generados en %s\n", len(msgs), *out)
}

func download(ref, name string) ([]byte, error) {
	url := fmt.Sprintf("https://raw.githubusercontent.com/FirebirdSQL/firebird/%s/src/include/firebird/impl/msg/%s.h", ref, name)
	resp, err := http.Get(url)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != 200 {
		return nil, fmt.Errorf("GET %s: %s", url, resp.Status)
	}
	return io.ReadAll(resp.Body)
}

// unescapeC resuelve las secuencias de escape de C usadas en los headers.
func unescapeC(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			i++
			switch s[i] {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case '"':
				b.WriteByte('"')
			case '\\':
				b.WriteByte('\\')
			default:
				b.WriteByte('\\')
				b.WriteByte(s[i])
			}
			continue
		}
		b.WriteByte(s[i])
	}
	return b.String()
}
